// Pointer files use an anchored final directory handle. Ancestors stay pinned;
// final-directory write sharing enables NT rename while delete sharing is denied.
using System;
using System.IO;
using System.Text;
using System.Runtime.InteropServices;
using C=HubSshMaintenanceCommon;
public sealed class HubSshMaintenancePointer : IDisposable {
  [StructLayout(LayoutKind.Sequential)] struct US {public ushort Length,Maximum;public IntPtr Buffer;}
  [StructLayout(LayoutKind.Sequential)] struct OA {public uint Length;public IntPtr Root,Name;public uint Attributes;public IntPtr SecurityDescriptor,Quality;}
  [StructLayout(LayoutKind.Sequential)] struct IO {public IntPtr Status;public UIntPtr Information;}
  [StructLayout(LayoutKind.Sequential)] struct FT {public uint Low,High;}
  [StructLayout(LayoutKind.Sequential)] struct FI {public uint Attributes;public FT Created,Access,Write;public uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
  [DllImport("ntdll.dll")] static extern int NtCreateFile(out IntPtr f,uint access,ref OA oa,out IO io,IntPtr size,uint attrs,uint share,uint disposition,uint options,IntPtr ea,uint length);
  [DllImport("ntdll.dll")] static extern int NtSetInformationFile(IntPtr f,out IO io,IntPtr info,uint size,int kind);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern IntPtr CreateFileW(string name,uint access,uint share,IntPtr sa,uint disposition,uint flags,IntPtr template);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileInformationByHandle(IntPtr f,out FI info);
  [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern uint GetFinalPathNameByHandleW(IntPtr f,StringBuilder name,uint length,uint flags);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool ReadFile(IntPtr f,byte[] bytes,uint count,out uint read,IntPtr overlapped);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool WriteFile(IntPtr f,byte[] bytes,uint count,out uint written,IntPtr overlapped);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool GetFileSizeEx(IntPtr f,out long size);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool FlushFileBuffers(IntPtr f);
  [DllImport("kernel32.dll",SetLastError=true)] static extern bool SetFilePointerEx(IntPtr f,long offset,out long result,uint origin);
  [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr f);
  readonly string root,fingerprint;HubPinnedRoot ancestors;IntPtr parent,handle;
  static void Need(bool ok,string code){C.Require(ok,code);}
  static void Status(int status){Need(status==0,"POINTER_NT_"+unchecked((uint)status).ToString("X8"));}
  static void Leaf(string name){Need(name!=null&&name.Length>0&&name.Length<=128&&name!="."&&name!=".."&&!name.EndsWith(".")&&!name.EndsWith(" ")&&System.Text.RegularExpressions.Regex.IsMatch(name,"^[A-Za-z0-9.-]+$"),"POINTER_LEAF_REJECTED");}
  static IntPtr Open(IntPtr parent,string name,uint access,uint disposition,bool directory,uint share){Leaf(name);IntPtr text=Marshal.StringToHGlobalUni(name),u=Marshal.AllocHGlobal(16),f=IntPtr.Zero;try{US us=new US();us.Buffer=text;us.Length=(ushort)(name.Length*2);us.Maximum=(ushort)(us.Length+2);Marshal.StructureToPtr(us,u,false);OA oa=new OA();oa.Length=48;oa.Root=parent;oa.Name=u;oa.Attributes=0x1040;IO io;int status=NtCreateFile(out f,access|0x100080,ref oa,out io,IntPtr.Zero,0x80,share,disposition,(directory?1U:0x40U)|0x200120,IntPtr.Zero,0);if(status!=0){if(f!=IntPtr.Zero&&f!=new IntPtr(-1))CloseHandle(f);Status(status);}return f;}finally{Marshal.FreeHGlobal(u);Marshal.FreeHGlobal(text);}}
  FI Check(IntPtr f,string expected,bool directory){FI info;Need(GetFileInformationByHandle(f,out info)&&(info.Attributes&0x400)==0&&((info.Attributes&0x10)!=0)==directory&&(directory||info.Links==1),"POINTER_OBJECT_CHANGED");StringBuilder p=new StringBuilder(32768);uint n=GetFinalPathNameByHandleW(f,p,32768,0);Need(n>0&&n<32768&&String.Equals(p.ToString(),"\\\\?\\"+expected,StringComparison.OrdinalIgnoreCase),"POINTER_PATH_CHANGED");return info;}
  public HubSshMaintenancePointer(string path,string expected){root=C.PathCheck(path);fingerprint=expected;string parentPath=Path.GetDirectoryName(root);try{ancestors=new HubPinnedRoot(parentPath,C.Fingerprint(parentPath));parent=CreateFileW(parentPath,0x1000a0,1,IntPtr.Zero,3,0x02200000,IntPtr.Zero);Need(parent!=IntPtr.Zero&&parent!=new IntPtr(-1),"POINTER_PARENT_OPEN_FAILED");handle=Open(parent,Path.GetFileName(root),0x22,1,true,3);Verify();}catch{Dispose();throw;}}
  public void Verify(){ancestors.Verify();FI info=Check(handle,root,true);ulong index=((ulong)info.IndexHigh<<32)|info.IndexLow;string current=C.Hash(C.Utf8.GetBytes(root+"\n"+info.Volume.ToString(System.Globalization.CultureInfo.InvariantCulture)+"\n"+index.ToString(System.Globalization.CultureInfo.InvariantCulture)));Need(current==fingerprint,"POINTER_ROOT_CHANGED");C.RootAcl(root);Check(handle,root,true);ancestors.Verify();}
  byte[] ReadHandle(IntPtr f,int max){long length,position;Need(GetFileSizeEx(f,out length)&&length>=0&&length<=max,"POINTER_FILE_BOUND");Need(SetFilePointerEx(f,0,out position,0),"POINTER_READ_FAILED");byte[] b=new byte[(int)length];uint n;Need(ReadFile(f,b,(uint)b.Length,out n,IntPtr.Zero)&&n==b.Length,"POINTER_READ_FAILED");return b;}
  public byte[] ReadOptional(string name,int max){Verify();IntPtr f=IntPtr.Zero;try{try{f=Open(handle,name,1,1,false,1);}catch(InvalidOperationException e){if(e.Message=="POINTER_NT_C0000034")return null;throw;}Check(f,Path.Combine(root,name),false);byte[] bytes=ReadHandle(f,max);Verify();return bytes;}finally{if(f!=IntPtr.Zero)CloseHandle(f);}}
  public void Create(string name,byte[] bytes){Verify();Need(bytes!=null&&bytes.Length>0&&bytes.Length<=65536,"POINTER_FILE_BOUND");IntPtr f=Open(handle,name,0x10003,2,false,1);try{Check(f,Path.Combine(root,name),false);uint n;Need(WriteFile(f,bytes,(uint)bytes.Length,out n,IntPtr.Zero)&&n==bytes.Length&&FlushFileBuffers(f),"POINTER_CREATE_INCOMPLETE");Need(HubSshMaintenanceStore.Equal(ReadHandle(f,65536),bytes),"POINTER_CREATE_READBACK_CHANGED");Verify();}finally{CloseHandle(f);}}
  public void Rename(string from,string to,bool replace,string sourceSHA){Need(!replace,"POINTER_UNVERIFIED_REPLACE_REJECTED");Verify();Leaf(from);Leaf(to);IntPtr file=Open(handle,from,0x10001,1,false,1),buffer=IntPtr.Zero;try{Check(file,Path.Combine(root,from),false);Need(C.Hash(ReadHandle(file,65536))==sourceSHA,"POINTER_SOURCE_CHANGED");byte[] name=Encoding.Unicode.GetBytes(to);int size=Math.Max(24,20+name.Length);buffer=Marshal.AllocHGlobal(size);for(int i=0;i<size;i++)Marshal.WriteByte(buffer,i,0);Marshal.WriteByte(buffer,replace?(byte)1:(byte)0);Marshal.WriteIntPtr(buffer,8,handle);Marshal.WriteInt32(buffer,16,name.Length);Marshal.Copy(name,0,IntPtr.Add(buffer,20),name.Length);IO io;Status(NtSetInformationFile(file,out io,buffer,(uint)size,10));Check(file,Path.Combine(root,to),false);Need(C.Hash(ReadHandle(file,65536))==sourceSHA,"POINTER_RENAME_READBACK_CHANGED");Verify();}finally{if(buffer!=IntPtr.Zero)Marshal.FreeHGlobal(buffer);CloseHandle(file);}}
  IntPtr OpenOptional(string name,uint access){try{return Open(handle,name,access,1,false,1);}catch(InvalidOperationException e){if(e.Message=="POINTER_NT_C0000034")return IntPtr.Zero;throw;}}
  void RenameHeld(IntPtr file,string to,string expectedSHA){Leaf(to);byte[] name=Encoding.Unicode.GetBytes(to);int size=Math.Max(24,20+name.Length);IntPtr buffer=Marshal.AllocHGlobal(size);try{for(int i=0;i<size;i++)Marshal.WriteByte(buffer,i,0);Marshal.WriteIntPtr(buffer,8,handle);Marshal.WriteInt32(buffer,16,name.Length);Marshal.Copy(name,0,IntPtr.Add(buffer,20),name.Length);IO io;Status(NtSetInformationFile(file,out io,buffer,(uint)size,10));Check(file,Path.Combine(root,to),false);Need(C.Hash(ReadHandle(file,65536))==expectedSHA,"POINTER_RENAME_READBACK_CHANGED");Verify();}finally{Marshal.FreeHGlobal(buffer);}}
  public void Publish(string from,string to,string sourceSHA,string expectedTargetSHA,string backup,Action displaced){Verify();Leaf(from);Leaf(to);Leaf(backup);Need(from!=to&&from!=backup&&to!=backup,"POINTER_NAME_COLLISION");IntPtr source=Open(handle,from,0x10001,1,false,1),target=IntPtr.Zero,saved=IntPtr.Zero;try{Check(source,Path.Combine(root,from),false);Need(C.Hash(ReadHandle(source,65536))==sourceSHA,"POINTER_SOURCE_CHANGED");target=OpenOptional(to,0x10001);if(expectedTargetSHA=="absent"){Need(target==IntPtr.Zero,"POINTER_TARGET_ALREADY_EXISTS");Need(ReadOptional(backup,65536)==null,"POINTER_BACKUP_UNEXPECTED");}else if(target!=IntPtr.Zero){Check(target,Path.Combine(root,to),false);Need(C.Hash(ReadHandle(target,65536))==expectedTargetSHA,"POINTER_TARGET_CHANGED");Need(ReadOptional(backup,65536)==null,"POINTER_BACKUP_ALREADY_EXISTS");RenameHeld(target,backup,expectedTargetSHA);if(displaced!=null)displaced();}else{saved=Open(handle,backup,1,1,false,1);Check(saved,Path.Combine(root,backup),false);Need(C.Hash(ReadHandle(saved,65536))==expectedTargetSHA,"POINTER_BACKUP_CHANGED");}RenameHeld(source,to,sourceSHA);}finally{if(saved!=IntPtr.Zero)CloseHandle(saved);if(target!=IntPtr.Zero)CloseHandle(target);CloseHandle(source);}}
  public void Delete(string name,string expectedSHA){Verify();IntPtr f=Open(handle,name,0x10001,1,false,1),buffer=Marshal.AllocHGlobal(1);try{Check(f,Path.Combine(root,name),false);Need(C.Hash(ReadHandle(f,65536))==expectedSHA,"POINTER_DELETE_CHANGED");Marshal.WriteByte(buffer,1);IO io;Status(NtSetInformationFile(f,out io,buffer,1,13));Verify();}finally{Marshal.FreeHGlobal(buffer);CloseHandle(f);}Need(ReadOptional(name,65536)==null,"POINTER_DELETE_UNVERIFIED");}
  public void Dispose(){if(handle!=IntPtr.Zero){CloseHandle(handle);handle=IntPtr.Zero;}if(parent!=IntPtr.Zero&&parent!=new IntPtr(-1)){CloseHandle(parent);parent=IntPtr.Zero;}if(ancestors!=null){ancestors.Dispose();ancestors=null;}}
}
